<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">ACCESS CONTROL</span><h2>الأدوار والصلاحيات</h2><p>تُطبّق الصلاحيات على الخادم. لا يوجد تعيين تلقائي لـ Super Administrator؛ يلزم تشغيل أداة bootstrap محليًا باختيار صريح.</p></div></section>
<section class="admin-v2-grid-2"><div class="admin-v2-panel"><div class="admin-v2-panel-head"><h3>الأدوار</h3><span><?=e(count($roles))?> أدوار</span></div><div class="admin-v2-module-list"><?php foreach($roles as $role):?><a href="/admin-v2/roles?role=<?=e($role['id'])?>" class="<?=((int)$role['id']===(int)($selectedRole['id']??0))?'active':''?>"><b><?=e((string)$role['slug'])?></b><span><strong><?=e((string)$role['name'])?></strong><small><?=e((string)($role['description']??''))?></small></span><i><?=e($role['assigned_count']??0)?> مستخدم</i></a><?php endforeach;?></div></div>
<div class="admin-v2-panel"><div class="admin-v2-panel-head"><h3><?=e((string)($selectedRole['name']??'تحرير دور'))?></h3><span><?=!empty($selectedRole['is_system'])?'دور مدمج':'دور مخصص'?></span></div><?php if($selectedRole):?><form method="post" action="/admin-v2/roles/save" class="admin-v2-actions"><input type="hidden" name="role_id" value="<?=e($selectedRole['id'])?>"><?=csrf_field()?><label>الاسم<input name="name" value="<?=e($selectedRole['name'])?>" required></label><label>الوصف<textarea name="description" rows="3"><?=e($selectedRole['description']??'')?></textarea></label><fieldset class="admin-v2-permission-grid"><legend>الصلاحيات</legend><?php foreach($permissions as $permission):?><label class="admin-v2-check"><input type="checkbox" name="permissions[]" value="<?=e($permission['slug'])?>" <?=in_array($permission['slug'],$selectedSlugs,true)?'checked':''?> <?=($selectedRole['slug']==='super_admin')?'disabled':''?>> <span><?=e($permission['name'])?><small><?=e($permission['slug'])?></small></span></label><?php endforeach;?></fieldset><?php if($selectedRole['slug']!=='super_admin'):?><button class="admin-v2-button primary" type="submit">حفظ الصلاحيات</button><?php else:?><p class="admin-v2-muted">الدور الأعلى محمي ولا يمكن تخفيضه من هذه الواجهة.</p><?php endif;?></form><?php else:?><div class="admin-v2-empty">لا يوجد دور محدد.</div><?php endif;?></div></section>
<section class="admin-v2-table-panel"><div class="admin-v2-panel-head"><h3>تعيين دور لحساب إداري</h3><span>يتطلب صلاحية إدارة الأدوار</span></div><form method="post" action="/admin-v2/roles/assign" class="admin-v2-filter"><?=csrf_field()?><select name="user_id" required><option value="">اختر المدير</option><?php foreach($admins as $admin):?><option value="<?=e($admin['id'])?>"><?=e($admin['name'])?> — <?=e($admin['username'])?> (<?=e($admin['role_names']??'بدون دور RBAC')?>)</option><?php endforeach;?></select><select name="role_id" required><option value="">اختر الدور</option><?php foreach($roles as $role):?><option value="<?=e($role['id'])?>"><?=e($role['name'])?></option><?php endforeach;?></select><button class="admin-v2-button primary" type="submit">تطبيق الدور</button></form></section>
